// 🕐 Utilidades
function sumarMinutosLocal(fechaStr, minutos) {
  const fecha = new Date(fechaStr);
  if (isNaN(fecha)) throw new Error(`Fecha inválida: ${fechaStr}`);
  fecha.setMinutes(fecha.getMinutes() + minutos);
  const [fechaPart, horaPart] = fecha.toISOString().split("T");
  const horaLocal = horaPart.substring(0, 5);
  return `${fechaPart}T${horaLocal}:00`;
}

function timeToMinutes(timeStr) {
  const [h, m] = timeStr.split(':').map(Number);
  return h * 60 + m;
}

// ✅ Obtener datos correctamente
const solicitudRaw = $('Code3').first();
const solicitud = solicitudRaw.json || solicitudRaw;

// ✅ Asegurar campos requeridos
if (!solicitud.Fecha || !solicitud.Fin) {
  return [{
    json: {
      error: 'Faltan campos Fecha o Fin en la solicitud',
      recibido: solicitud
    }
  }];
}

// ✅ Extraer fecha y horas
const solicitudFecha = solicitud.Fecha.split('T')[0];
const solicitudInicio = solicitud.Fecha.split('T')[1].substring(0, 5);
const solicitudFin = solicitud.Fin.split('T')[1].substring(0, 5);

// ✅ Turnos ocupados
const pilar1Ocupados = $('PILAR_').all().map(i => i.json).flat();
const pilar2Ocupados = $('PILAR_3').all().map(i => i.json).flat();
const pilar4Ocupados = $('PILAR_4').all().map(i => i.json).flat();

// ✅ Conflictos
function tieneConflicto(fecha, inicio, fin, ocupados) {
  if (!Array.isArray(ocupados)) return false;
  const inicioMin = timeToMinutes(inicio);
  const finMin = timeToMinutes(fin);
  return ocupados.some(o => {
    if (o.dia !== fecha) return false;
    const oIni = timeToMinutes(o.inicio);
    const oFin = timeToMinutes(o.final);
    return inicioMin < oFin && finMin > oIni;
  });
}

// ✅ Disponibilidad
const p1Disp = !tieneConflicto(solicitudFecha, solicitudInicio, solicitudFin, pilar1Ocupados);
const p2Disp = !tieneConflicto(solicitudFecha, solicitudInicio, solicitudFin, pilar2Ocupados);
const p4Disp = !tieneConflicto(solicitudFecha, solicitudInicio, solicitudFin, pilar4Ocupados);

// 🔑 👉 CALENDAR DESDE Get_Reglas1
