// Convierte "H:MM:SS" → minutos
function tiempoAHorasMinutos(tiempoStr) {
  const [h, m] = (tiempoStr || "0:30:00").split(":").map(Number);
  return (h * 60) + (m || 0);
}

// HH:MM -> minutos
function timeToMinutes(t) {
  const [h, m] = t.split(":").map(Number);
  return h * 60 + m;
}

// minutos -> HH:MM
function minutesToTime(mins) {
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return `${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}`;
}

